using System.Text.Json;
using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns application configuration data including feature flags and limits.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            MaxItemsPerPage = 50,
            DefaultLanguage = "en-US",
            Features = new
            {
                DarkMode = true,
                BetaFeatures = false,
                Notifications = true
            },
            ApiVersion = "v2"
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/endpoints",
        Name = "API Endpoints",
        MimeType = "application/json"),
     Description("Returns the configured API endpoint URLs.")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            Users = "/api/v2/users",
            Products = "/api/v2/products",
            Orders = "/api/v2/orders"
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Validates whether a configuration key exists and returns its value.")]
    public static string ValidateConfigKey(
        [Description("The configuration key to look up (e.g., 'MaxItemsPerPage')")] string key)
    {
        var knownKeys = new Dictionary<string, string>
        {
            ["MaxItemsPerPage"] = "50",
            ["DefaultLanguage"] = "en-US",
            ["ApiVersion"] = "v2",
            ["DarkMode"] = "true",
            ["BetaFeatures"] = "false",
            ["Notifications"] = "true"
        };

        return knownKeys.TryGetValue(key, out var value)
            ? $"Key '{key}' = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", knownKeys.Keys)}";
    }
}

